import re as _re
import __future__

def _t():
    code = 'from __future__ import barry_as_FLUFL\n2 {0} 3'
    compile(code.format('<>'), '<BDFL test>', 'exec', __future__.CO_FUTURE_BARRY_AS_BDFL)
    try:
        compile(code.format('!='), '<FLUFL test>', 'exec', __future__.CO_FUTURE_BARRY_AS_BDFL)
    except SyntaxError as _exc:
        cm = _exc
    else:
        raise AssertionError('assertRaises: did not raise')
    assert _re.search("with Barry as BDFL, use '<>' instead of '!='", str(cm)), ('assertRegex', str(cm), "with Barry as BDFL, use '<>' instead of '!='")
    assert '2 != 3' in cm.text, ('assertIn', '2 != 3', cm.text)
    assert cm.filename == '<FLUFL test>', ('assertEqual', cm.filename, '<FLUFL test>')
    assert cm.lineno == 2, ('assertEqual', cm.lineno, 2)
    assert cm.offset == 3, ('assertEqual', cm.offset, 3)
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')

